  setCurrentRide(null); // Clear so polling doesn't conflict
  setShowRating(true);

const handleSubmitRating = async () => {
  const rideToRate = completedRideData || currentRide;
  if (!rideToRate) return;
  try {
    await fetch(`${API_BASE}/api/rides/${rideToRate.id}/rate-passenger`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        rating: ratingValue,
        comment: ratingComment
      })
    });
  } catch (err) {
    console.error("Failed to submit passenger rating:", err);
  }

  alert('Passenger feedback registered successfully!');
  if (queuedRide) {
    setCurrentRide(queuedRide);
    setQueuedRide(null);
    alert(`Ride completed. Your queued trip to ${queuedRide.dropoff} is now active!`);
  } else {
    setCurrentRide(null);
  }
  setShowRating(false);
  setCompletedRideData(null);
  setRatingValue(5);
  setRatingComment('');
  fetchWallet();
};

